"use client"

import { useEffect, useRef, useState } from "react"
import { motion, useReducedMotion } from "motion/react"

import { BUTTON } from "@/components/ui/control-classes"
import { Line, PILL_32, PrimaryButton, RowField, Segments, TICKET_WIDTH, ink } from "@/components/ui/swap-ticket-field"
import { cn } from "@/lib/utils"

/* Quick Ticket, written new through ssych-component (2026-09-29).
   What it is for: placing a small order from a watchlist row without leaving it. At rest
   it is one line (symbol, last price, Buy, Sell); pressed, it opens into a ticket.
   Read first: the white button. It names the order it will place.
   The pointer: Buy or Sell on the line opens the ticket on that side; the two switches
   slide a fill; minus and plus step the size and the size can be typed; "Use last" puts
   the last price in the limit field; Close or Escape folds it back to the line.
   Sketch used: src/components/lab/QuickTicket.tsx. Kept: the line that becomes a ticket,
   side, market or limit, the size stepper, the limit price with its reset, the estimate
   and the placed state that folds the ticket away. It was a floating popover; here it opens
   in the flow, and it opens already unfolded so the ticket can be seen.
   Changed: no card, outline or shadow, one family (it set figures in mono), the type
   switch no longer uses a blue, the button is white, icons became words.
   Motion pass (2026-09-30): the ticket and the limit field open through grid rows 0fr to
   1fr in 250ms (no height animation); the button's label swaps in place and "Order
   placed" draws a green check; presses sink to 0.97 on the lift spring.
   Formulas:
   · price     market: the last price · limit: the typed limit
   · estimate  size × price
   · from last (limit − last) ÷ last × 100, limit orders only
   2026-10-02: surfaces at 7% (raised blocks white in light, 12% in dark) so cards read on white and on black.
   2026-10-02 audit: it rests folded, as the one line, and Buy or Sell unfolds it
   (defaultOpen is false; spec 13.8, nothing open on load). 320 wide like the other two
   tickets, and cut from the family's parts (swap-ticket-field.tsx): the switch material with
   the side as a 6px dot, the 48px round row fields, the 48px white primary. The folded Buy
   and Sell are the control material with a dot before the word (they were coloured words on a
   6% fill). The button reads "Buy NVDA" (the size is in its field) and the distance from
   last moved into the estimate's tip.
   Formulas, where each is shown: estimate on its line, its tip shows size × price and, for a
   limit, the distance from last.
   2026-10-02 round 2: (his notes after the side by side, applied to every ticket): no dots. The
   folded Buy and Sell are tinted in their hue (14% fill, the word in the hue); in the open
   ticket the chosen side is its pill tinted the same way and the other stays in ink; the dot
   before the button's label is gone. Nothing shifts: switching Market and Limit used to fold the
   limit row away and shorten the ticket; the row now stays, as the editable limit with Use last,
   or as the read-only last price the market order fills at, so the ticket keeps its height.
   The fields show focus on their own edge. */

const EASE = [0.16, 1, 0.3, 1] as const
const GREEN = "var(--chart-up)"
const RED = "var(--chart-down)"
const PLACED_MS = 1200
/** the placed check: green, pulled toward the page ground so it holds on the white button */
const PLACED_INK = "color-mix(in srgb, var(--chart-up) 80%, var(--background))"
const GROW = "grid transition-[grid-template-rows] duration-[250ms] ease-[cubic-bezier(0.22,1,0.36,1)] motion-reduce:transition-none"
const GROW_INNER = "min-h-0 overflow-hidden transition-[opacity,filter] duration-[250ms] ease-[cubic-bezier(0.22,1,0.36,1)]"

export type QuickTicketSide = "buy" | "sell"
export type QuickTicketType = "market" | "limit"

export interface QuickTicketOrder {
  side: QuickTicketSide
  type: QuickTicketType
  symbol: string
  size: number
  /** the price the order is worked at */
  limit: number
  total: number
}

export interface QuickTicketProps {
  symbol?: string
  last?: number
  side?: QuickTicketSide
  size?: number
  type?: QuickTicketType
  /** opening limit price */
  limit?: number
  /** whether it opens unfolded (folded by default since the 2026-10-02 audit) */
  defaultOpen?: boolean
  onSubmit?: (order: QuickTicketOrder) => void
  className?: string
}

const usd = (n: number) => `$${n.toLocaleString("en-US", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`

/**
 * A watchlist line that opens into an order ticket where it stands. Side and type are two
 * quiet switches, the size steps or types, and the white button reads back the order.
 */
export function QuickTicket({
  symbol = "NVDA",
  last = 121.44,
  side: initialSide = "buy",
  size: initialSize = 10,
  type: initialType = "limit",
  limit: initialLimit = 120.9,
  defaultOpen = false,
  onSubmit,
  className,
}: QuickTicketProps) {
  const reduced = useReducedMotion()
  const [open, setOpen] = useState(defaultOpen)
  const [side, setSide] = useState<QuickTicketSide>(initialSide)
  const [type, setType] = useState<QuickTicketType>(initialType)
  const [sizeStr, setSizeStr] = useState(String(initialSize))
  const [limitStr, setLimitStr] = useState((initialLimit ?? last).toFixed(2))
  const [placed, setPlaced] = useState(false)
  const timer = useRef<ReturnType<typeof setTimeout> | null>(null)
  useEffect(() => () => void (timer.current && clearTimeout(timer.current)), [])

  const size = parseInt(sizeStr, 10) || 0
  const price = type === "limit" ? parseFloat(limitStr) || 0 : last
  const total = size * price
  const away = last > 0 && price > 0 ? ((price - last) / last) * 100 : 0
  const buy = side === "buy"
  const state = placed ? "placed" : size <= 0 ? "size" : price <= 0 ? "price" : "ready"
  const verdict = state === "placed" ? "Order placed" : state === "size" ? "Enter a size" : state === "price" ? "Enter a price" : `${buy ? "Buy" : "Sell"} ${symbol}`

  const unfold = (s: QuickTicketSide) => {
    setSide(s)
    setPlaced(false)
    setOpen(true)
  }
  const submit = () => {
    if (state !== "ready") return
    onSubmit?.({ side, type, symbol, size, limit: price, total })
    setPlaced(true)
    timer.current = setTimeout(() => {
      setPlaced(false)
      setOpen(false)
    }, PLACED_MS)
  }
  const step = (by: number) => setSizeStr(String(Math.max(1, size + by)))

  const stepper = (label: string, by: number, glyph: string) => (
    <button type="button" onClick={() => step(by)} aria-label={label} className={cn("h-8 w-8 shrink-0 text-[14px]", BUTTON)}>
      {glyph}
    </button>
  )

  return (
    <div
      className={cn(TICKET_WIDTH, "tabular-nums [--ink-l:0.5] dark:[--ink-l:1]", className)}
      role="group"
      aria-label={`${symbol} quick ticket, last ${usd(last)}${open ? `, ${verdict}` : ""}`}
      onKeyDown={(e) => {
        if (e.key === "Escape") setOpen(false)
      }}
    >
      <div className="flex h-8 items-center gap-2 px-1">
        <span className="text-[13px] font-medium text-foreground/90">{symbol}</span>
        <span className="text-[12px] text-foreground/60">Last {usd(last)}</span>
        <span className="ml-auto flex items-center gap-1">
          {open ? (
            <button type="button" onClick={() => setOpen(false)} className={cn("h-7 px-3 text-[11.5px]", BUTTON)}>
              Close
            </button>
          ) : (
            (["buy", "sell"] as const).map((s) => {
              const hue = s === "buy" ? GREEN : RED
              return (
                /* the side's own hue on the pill: a 14% fill and the word in the hue, a touch more under the pointer */
                <button
                  key={s}
                  type="button"
                  onClick={() => unfold(s)}
                  aria-label={`${s === "buy" ? "Buy" : "Sell"} ${symbol}`}
                  className="inline-flex h-7 items-center rounded-full bg-[color-mix(in_srgb,var(--side)_14%,transparent)] px-3 text-[11.5px] font-medium outline-none transition-[background-color,scale] duration-150 hover:bg-[color-mix(in_srgb,var(--side)_22%,transparent)] focus-visible:bg-[color-mix(in_srgb,var(--side)_22%,transparent)] active:scale-[0.97] motion-reduce:active:scale-100"
                  style={{ ["--side" as string]: hue, color: ink(hue) }}
                >
                  {s === "buy" ? "Buy" : "Sell"}
                </button>
              )
            })
          )}
        </span>
      </div>

      {/* grid rows 0fr to 1fr: the ticket opens without measuring or animating height; it
          stays mounted, so folded it is inert and hidden from a screen reader */}
      <div className={GROW} style={{ gridTemplateRows: open ? "1fr" : "0fr" }} inert={!open} aria-hidden={!open}>
        <div className={GROW_INNER} style={{ opacity: open ? 1 : 0, filter: open || reduced ? "none" : "blur(2px)" }}>
          <div className="pt-2">
            <Segments
              name="Side"
              value={side}
              onChange={setSide}
              options={[
                { value: "buy", label: "Buy", hue: GREEN },
                { value: "sell", label: "Sell", hue: RED },
              ]}
            />
            <Segments
              className="mt-1.5"
              name="Type"
              value={type}
              onChange={setType}
              options={[
                { value: "market", label: "Market" },
                { value: "limit", label: "Limit" },
              ]}
            />

            <div className="mt-3 flex flex-col">
              <RowField
                label="Shares"
                value={sizeStr}
                onChange={setSizeStr}
                places={0}
                inputMode="numeric"
                ariaLabel={`Shares of ${symbol}`}
                end={
                  <span className="flex gap-1">
                    {stepper("One share fewer", -1, "−")}
                    {stepper("One share more", 1, "+")}
                  </span>
                }
              />
              {/* the second row stays in both types, so switching them never changes the height */}
              {type === "limit" ? (
                <RowField
                  className="mt-1.5"
                  label="Limit"
                  value={limitStr}
                  onChange={setLimitStr}
                  places={2}
                  placeholder="0.00"
                  ariaLabel="Limit price in dollars"
                  end={
                    <button type="button" onClick={() => setLimitStr(last.toFixed(2))} className={PILL_32}>
                      Use last
                    </button>
                  }
                />
              ) : (
                <RowField className="mt-1.5" label="At market" value={last.toFixed(2)} ariaLabel="Market order, fills at the last price in dollars" />
              )}
            </div>

            <div role="status" className="mt-3 px-1">
              <Line
                label="Estimate"
                strong
                value={usd(total)}
                tip={`${size} × ${usd(price)}${type === "limit" ? `; the limit is ${away >= 0 ? "+" : "−"}${Math.abs(away).toFixed(2)}% from last (${usd(last)})` : ", at the last price"}`}
              />
            </div>

            {/* the one loud control; its label is the order it will place */}
            <PrimaryButton
              className="mt-4"
              state={`${state}-${side}`}
              disabled={state !== "ready"}
              onClick={submit}
              label={
                <>
                  {placed ? (
                    <svg aria-hidden width="12" height="12" viewBox="0 0 12 12" fill="none">
                      <motion.path
                        d="M2.5 6.2 5 8.6l4.5-5"
                        stroke={PLACED_INK}
                        strokeWidth="1.8"
                        strokeLinecap="round"
                        strokeLinejoin="round"
                        initial={reduced ? false : { pathLength: 0 }}
                        animate={{ pathLength: 1 }}
                        transition={{ duration: 0.3, ease: EASE, delay: 0.08 }}
                      />
                    </svg>
                  ) : null}
                  {verdict}
                </>
              }
            />
          </div>
        </div>
      </div>
    </div>
  )
}

/* Control classes: the library's control material for components that ship on their own
   (2026-10-02, the audit's pattern 11). src/components/library/controls.ts is the site's
   copy; components used to paste its look in as a flat 8% fill "so the file ships alone",
   and those copies never turned white on a raised light surface. These read the same
   tokens WITH a fallback, so they follow the site's raised-surface rule here and still
   draw correctly in a buyer's app that has no such tokens. Shipped beside every component
   that imports it (scripts/build-registry.mjs bundles ui helpers automatically).

   Whole class strings, never assembled from pieces: Tailwind reads this file as text. */

/** what is ON in a switcher. Light (his call, 2026-10-02, after the inline slider): a WHITE
 *  pill with a hairline and a soft shadow on the grey track. Dark: the 8% thumb */
export const THUMB =
  "bg-white shadow-[0_0_0_1px_var(--light-outline,rgba(0,0,0,0.09)),0_1px_3px_rgba(0,0,0,0.08)] dark:bg-[var(--control-fill,color-mix(in_oklab,var(--foreground)_8%,transparent))] dark:shadow-[var(--control-shadow,inset_0_1px_0_0_color-mix(in_srgb,var(--foreground)_6%,transparent))]"

/** what a switcher's options sit in; its 2px padding is the gap the thumb keeps. Light: a
 *  light grey track with no outline, the white pill sits in it. Dark: a hairline, no fill */
export const TRACK = "rounded-full border border-transparent bg-[color-mix(in_srgb,var(--foreground)_5%,var(--background))] p-0.5 dark:border-foreground/[0.04] dark:bg-transparent"

/** an option that is off: the label alone answers the pointer */
export const SEGMENT_OFF = "text-foreground/60 hover:text-foreground/90"

/** a secondary button: the thumb standing alone; size it with h-7 / h-9 and px */
export const BUTTON =
  "inline-flex items-center justify-center gap-1.5 rounded-full bg-[var(--control-fill,color-mix(in_oklab,var(--foreground)_8%,transparent))] shadow-[var(--control-shadow,inset_0_1px_0_0_color-mix(in_srgb,var(--foreground)_6%,transparent))] text-foreground/90 outline-none transition-[color,background-color,scale] duration-150 hover:bg-[var(--control-fill-hover,color-mix(in_oklab,var(--foreground)_12%,transparent))] focus-visible:bg-[var(--control-fill-hover,color-mix(in_oklab,var(--foreground)_12%,transparent))] active:scale-[0.97] disabled:pointer-events-none disabled:opacity-40 motion-reduce:active:scale-100"

/** an icon-only control: no fill at rest, a faint one under the pointer */
export const ICON_BUTTON =
  "inline-flex items-center justify-center rounded-full text-foreground/60 outline-none transition-[color,background-color] duration-150 hover:bg-foreground/[0.06] hover:text-foreground/90 focus-visible:bg-foreground/[0.06]"

/** a field: the track with just enough fill to read as somewhere to type */
export const FIELD =
  "rounded-full border border-foreground/[0.04] bg-[var(--field-fill,color-mix(in_oklab,var(--foreground)_5%,transparent))] text-foreground/90 outline-none transition-[background-color,border-color] duration-150 placeholder:text-foreground/45 focus:border-foreground/[0.12]"

/** the one loud button of a form: 48px, full width, the foreground filled (the dashboards'
 *  Modal primary). A ticket, a swap, a confirm: one of these and nothing louder */
export const BUTTON_PRIMARY =
  "inline-flex h-12 w-full items-center justify-center gap-2 rounded-full bg-foreground/[0.92] text-[14px] font-medium text-background outline-none transition-[background-color,scale,opacity] duration-150 hover:bg-foreground focus-visible:bg-foreground active:scale-[0.98] disabled:pointer-events-none disabled:opacity-40 motion-reduce:active:scale-100"

/** a component's own card, field or block (spec 14.8). Dark: a #121212 fill on black. Light
 *  (his call, 2026-10-02: "on light the card background is too dark, it can just be white, a
 *  quiet outline and a small shadow"): white, a 1px hairline (Kraken's #e7e6e9, or 9% ink in an app without the token) and a
 *  barely there shadow,
 *  drawn as box shadows so the outline takes no layout */
export const SURFACE =
  "bg-background shadow-[0_0_0_1px_var(--light-outline,color-mix(in_srgb,var(--foreground)_9%,transparent)),0_1px_2px_rgba(0,0,0,0.04)] dark:bg-[color-mix(in_srgb,var(--foreground)_7%,var(--background))] dark:shadow-none"

/** a block sitting ON a surface: a faint 4% grey inside a white card in light, #1f1f1f in dark */
export const RAISED = "bg-[color-mix(in_srgb,var(--foreground)_4%,var(--background))] dark:bg-[color-mix(in_srgb,var(--foreground)_12%,var(--background))]"

"use client"

import { useId, useState, type CSSProperties, type ReactNode } from "react"
import { AnimatePresence, motion, useReducedMotion } from "motion/react"
import { ArrowDown } from "lucide-react"

import { BUTTON, BUTTON_PRIMARY, SEGMENT_OFF, SURFACE, THUMB, TRACK } from "@/components/ui/control-classes"
import { Tip } from "@/components/ui/amount-tip"
import { cn } from "@/lib/utils"

/* Ticket parts (2026-10-02 audit, pattern 7): the one field, switch, flip, line and primary
   that the order tickets (Leverage, Order, Quick) and the swaps (Swap Ticket, Cross Chain
   Swap, Swap Confirm) are cut from, so the six forms read as two families of one product at
   one width. Before this the fields ran 8, 20, 22, 24 and 26px corners, the primaries were
   hand written at 44px and every form drew its own pills. The look follows the dashboards'
   SwapPanel (src/components/lab/screen/SwapPanel.tsx): fields on the surface step, a round
   flip on the seam with a ring of the ground, the 48px primary.
   Corners nest (spec 13.10):
   · AmountBox holds a 32px chip (radius 16) 12px in from its top right corner: 28
   · RowField is a 48px control: fully round, and what sits in its end is a 32px pill 8px in
   · Segments is the switch material: TRACK, THUMB, SEGMENT_OFF, a 28px pill in a 2px track
   2026-10-02 round 2: his notes after the side by side. Segments takes a `hue` per option: the
   chosen side's thumb is tinted in it (14%) and its label set in it, the other stays in ink; the
   6px dot is gone (an old `dot` is read as the hue and no longer drawn). AmountBox takes `seam`:
   the row that meets the flip keeps a 60px lane clear in its middle, so a balance or a chip
   never runs under the arrow. Focus sits on the field's own edge: a field's ground brightens
   its inset line to 20% while it holds focus, and every input here drops the page's blue
   outline (outline-none!, important because the site's :focus-visible rule is unlayered).
   PrimaryButton takes `hue` and `onHue` so a form whose action has a direction can wear it. */

const TAB_EASE = [0.22, 1, 0.36, 1] as const
const EASE = [0.16, 1, 0.3, 1] as const

/** the family width: every ticket and swap is this wide (spec 13.9) */
export const TICKET_WIDTH = "w-[320px] max-w-full"

/** a field's ground: the surface step, a touch deeper while something in it has focus */
const GROUND = cn(SURFACE, "transition-[background-color,box-shadow] duration-150 focus-within:shadow-[inset_0_0_0_1px_color-mix(in_srgb,var(--foreground)_20%,transparent)]")

/** an input inside a field: no outline of its own, the field's edge shows the focus. The
 *  important mark beats an unlayered page rule such as `:focus-visible { outline }` */
export const BARE_INPUT = "outline-none! no-focus-ring"

/** the lane kept clear over the flip: the 44px disc and its ring, plus 8px each side */
const SEAM_ROW = "grid grid-cols-[minmax(0,1fr)_60px_minmax(0,1fr)] items-center"

/** A hue as text: its lightness is capped in the light theme so small figures stay readable. */
export const ink = (c: string) => `oklch(from ${c} min(l, var(--ink-l, 1)) c h)`

/**
 * The amount field: a label top left and a chip top right (the token, or Max), the typed or
 * quoted amount under them, and a foot line (its worth on the left, the balance on the right).
 */
export function AmountBox({
  label,
  aside,
  children,
  foot,
  footAside,
  seam,
  className,
}: {
  label: ReactNode
  aside?: ReactNode
  children: ReactNode
  foot?: ReactNode
  footAside?: ReactNode
  /** which edge meets the flip: "bottom" for the field above it (its foot keeps the middle
   *  clear), "top" for the field under it (its label row keeps the middle clear) */
  seam?: "top" | "bottom"
  className?: string
}) {
  const top = seam === "top"
  const bottom = seam === "bottom"
  return (
    <div className={cn("flex flex-col gap-2 rounded-[28px] p-3", GROUND, className)}>
      <div className={cn("min-h-8", top ? cn(SEAM_ROW, "px-1") : "flex items-center justify-between gap-2 pl-1")}>
        <span className="min-w-0 truncate text-[12px] text-foreground/60">{label}</span>
        {top && <span aria-hidden />}
        {top ? <span className="flex min-w-0 justify-end">{aside}</span> : aside}
      </div>
      {/* one height for a 22px and a 17px figure, so two fields match and the flip sits on the seam */}
      <div className="flex h-7 min-w-0 items-center gap-2 px-1">{children}</div>
      {(foot || footAside) && (
        <div className={cn("min-h-6 px-1 text-[12px] text-foreground/60", bottom ? SEAM_ROW : "flex items-center justify-between gap-2")}>
          <span className="min-w-0 truncate">{foot}</span>
          {bottom && <span aria-hidden />}
          {footAside ? <span className={cn("flex items-center gap-1.5", bottom ? "min-w-0 justify-end" : "shrink-0")}>{footAside}</span> : bottom && <span />}
        </div>
      )}
    </div>
  )
}

/** the big figure in an AmountBox: typed (an input) or quoted (a span) at 22px or 17px */
export const amountText = (size: "lead" | "second", empty: boolean) =>
  cn(
    "w-full min-w-0 bg-transparent font-semibold leading-none tracking-[-0.02em] caret-foreground placeholder:text-foreground/35",
    BARE_INPUT,
    size === "lead" ? "text-[22px]" : "text-[17px]",
    empty ? "text-foreground/35" : "text-foreground/90",
  )

/**
 * A one line field: a 48px pill on the surface, its label on the left, the value typed on the
 * right, a unit or a small button (32px) at its end.
 */
export function RowField({
  label,
  value,
  onChange,
  places,
  unit,
  end,
  placeholder = "0",
  inputMode = "decimal",
  pattern,
  ariaLabel,
  align = "right",
  className,
}: {
  label: string
  value: string
  /** leave out for a field that only shows a figure */
  onChange?: (v: string) => void
  /** decimal places a typed number may carry; leave out with `pattern` for free text */
  places?: number
  unit?: string
  end?: ReactNode
  placeholder?: string
  inputMode?: "decimal" | "numeric" | "text"
  /** a custom test for what may be typed */
  pattern?: RegExp
  ariaLabel?: string
  align?: "left" | "right"
  className?: string
}) {
  const test = pattern ?? (places === undefined ? undefined : places === 0 ? /^\d{0,9}$/ : new RegExp(`^\\d*\\.?\\d{0,${places}}$`))
  return (
    <label className={cn("flex h-12 items-center gap-2 rounded-full pl-5", end ? "pr-2" : "pr-5", GROUND, className)}>
      <span className="shrink-0 text-[12px] text-foreground/60">{label}</span>
      <input
        value={value}
        onChange={(e) => {
          if (!test || test.test(e.target.value)) onChange?.(e.target.value)
        }}
        readOnly={!onChange}
        tabIndex={onChange ? 0 : -1}
        placeholder={placeholder}
        inputMode={inputMode}
        aria-label={ariaLabel ?? (unit ? `${label} in ${unit}` : label)}
        className={cn(
          "min-w-0 flex-1 bg-transparent text-[14px] font-semibold caret-foreground placeholder:text-foreground/35",
          BARE_INPUT,
          align === "right" ? "text-right" : "text-left",
          onChange ? "text-foreground/90" : "text-foreground/60",
        )}
      />
      {unit && <span className="shrink-0 text-[12px] text-foreground/60">{unit}</span>}
      {end}
    </label>
  )
}

/** a small pill inside a field or a foot line: Max, Half, Use last, a stepper */
export const PILL = cn("h-6 px-2.5 text-[11px] font-medium", BUTTON)
export const PILL_32 = cn("h-8 px-3 text-[12px]", BUTTON)

export type SegmentOption<T extends string> = {
  value: T
  label: string
  /** the side's hue: the chosen pill is tinted in it and its label set in it (Buy green, Sell red) */
  hue?: string
  /** before round 2 a 6px dot; now read as `hue` when no hue is given, and never drawn */
  dot?: string
}

/**
 * The switch: the library's segmented material (TRACK, THUMB, SEGMENT_OFF) at full width,
 * 11.5px. An option with a hue shows it on the chosen state itself: the thumb tinted 14% in
 * it and the label in it; the option that is off stays in ink (brief rule 3, no dots).
 */
export function Segments<T extends string>({
  name,
  options,
  value,
  onChange,
  className,
}: {
  name: string
  options: SegmentOption<T>[]
  value: T
  onChange: (v: T) => void
  className?: string
}) {
  const reduced = useReducedMotion()
  const uid = useId().replace(/:/g, "")
  return (
    <div role="radiogroup" aria-label={name} className={cn("grid gap-0.5", TRACK, className)} style={{ gridTemplateColumns: `repeat(${options.length}, 1fr)` }}>
      {options.map((o) => {
        const on = o.value === value
        const hue = o.hue ?? o.dot
        /* dark: 14% of the hue over the thumb. Light (2026-10-02: "grey and desaturated on the grey
           ground"): the hue mixed into WHITE, lighter and clearer than a tint over grey */
        /* 2026-10-06: light-dark() picked the light side in any app that does not declare
           color-scheme: dark, so a dark app showed a mint pill. The hue rides a variable and the
           two sides are classes, which follow the .dark class every shadcn app sets */
        const tint = on && hue ? ({ "--seg-hue": hue } as CSSProperties) : undefined
        const tintClass = tint ? "bg-[color-mix(in_srgb,var(--seg-hue)_16%,#ffffff)] dark:bg-[color-mix(in_srgb,var(--seg-hue)_14%,transparent)]" : ""
        return (
          <button
            key={o.value}
            type="button"
            role="radio"
            aria-checked={on}
            onClick={() => onChange(o.value)}
            className={cn(
              "group relative flex h-7 items-center justify-center gap-1.5 rounded-full text-[11.5px] font-medium outline-none transition-colors duration-200",
              on ? "text-foreground/90" : SEGMENT_OFF,
            )}
            style={on && hue ? { color: ink(hue) } : undefined}
          >
            {on &&
              (reduced ? (
                <span aria-hidden className={cn("absolute inset-0 rounded-full", THUMB, tintClass)} style={tint} />
              ) : (
                <motion.span aria-hidden layoutId={`${uid}-thumb`} className={cn("absolute inset-0 rounded-full", THUMB, tintClass)} style={tint} transition={{ duration: 0.25, ease: TAB_EASE }} />
              ))}
            {/* the press answers on the label, so the thumb's glide measures an unscaled button */}
            <span className="relative inline-block transition-transform duration-150 group-active:scale-[0.97] motion-reduce:transition-none motion-reduce:group-active:scale-100">{o.label}</span>
          </button>
        )
      })}
    </div>
  )
}

/**
 * The flip on the seam between two fields (the dashboards' SwapPanel): a 36px disc one step
 * raised, cut out of both fields by a 4px ring of the ground, turning half a turn per press.
 */
/* light (his call, 2026-10-02): a lighter grey, 6% ink (10% on hover), and no white ring
   (the 4px border stays as a transparent gap so the size and centring are unchanged); dark
   keeps 12% / 18% and the ring in the page colour */
export function FlipButton({ onClick, label, disabled }: { onClick: () => void; label: string; disabled?: boolean }) {
  const reduced = useReducedMotion()
  const [turns, setTurns] = useState(0)
  return (
    <motion.button
      type="button"
      aria-label={label}
      disabled={disabled}
      onClick={() => {
        setTurns((t) => t + 1)
        onClick()
      }}
      animate={{ rotate: turns * 180 }}
      whileTap={reduced ? undefined : { scale: 0.94 }}
      transition={reduced ? { duration: 0 } : { rotate: { duration: 0.3, ease: EASE }, scale: { type: "spring", stiffness: 500, damping: 30 } }}
      className="absolute left-1/2 top-1/2 z-10 -ml-[22px] -mt-[22px] grid h-9 w-9 place-items-center rounded-full border-4 border-transparent bg-clip-padding dark:border-background dark:bg-clip-border bg-[color-mix(in_srgb,var(--foreground)_6%,var(--background))] text-foreground/85 outline-none transition-colors duration-150 hover:bg-[color-mix(in_srgb,var(--foreground)_10%,var(--background))] focus-visible:bg-[color-mix(in_srgb,var(--foreground)_10%,var(--background))] dark:bg-[color-mix(in_srgb,var(--foreground)_12%,var(--background))] dark:hover:bg-[color-mix(in_srgb,var(--foreground)_18%,var(--background))] dark:focus-visible:bg-[color-mix(in_srgb,var(--foreground)_18%,var(--background))] disabled:text-foreground/40"
      style={{ boxSizing: "content-box" }}
    >
      <ArrowDown size={16} aria-hidden />
    </motion.button>
  )
}

/** a label and value line under the fields; with `tip` the value shows its formula on hover */
export function Line({ label, value, tip, strong = false, hue }: { label: string; value: ReactNode; tip?: ReactNode; strong?: boolean; hue?: string }) {
  const v = (
    <span className={cn("text-foreground/90", strong && "font-semibold", tip && "cursor-default underline decoration-foreground/20 decoration-dotted underline-offset-[3px] outline-none! transition-[text-decoration-color] duration-150 focus-visible:decoration-foreground/70")} style={hue ? { color: ink(hue) } : undefined} tabIndex={tip ? 0 : undefined}>
      {value}
    </span>
  )
  return (
    <div className="flex items-baseline justify-between gap-3 text-[12px]">
      <span className="text-foreground/60">{label}</span>
      {tip ? <Tip tip={tip}>{v}</Tip> : v}
    </div>
  )
}

/**
 * The one loud button of a ticket: BUTTON_PRIMARY, 48px, white. Its label is the state of the
 * ticket and swaps in place (4px, 2px blur, 150ms) only when the state changes, so typing a
 * figure never replays it. With `hue` (and the ink for it, `onHue`) it is filled in that hue
 * instead, for an action that has a direction.
 */
export function PrimaryButton({
  state,
  label,
  disabled,
  busy,
  onClick,
  hue,
  onHue = "var(--on-accent, var(--background))",
  className,
}: {
  /** what the label is keyed on: change it only on a change of state */
  state: string
  label: ReactNode
  disabled?: boolean
  busy?: boolean
  onClick?: () => void
  /** a fill in place of the white (e.g. var(--chart-up) for a buy); leave out for white */
  hue?: string
  /** the label's ink on that fill */
  onHue?: string
  className?: string
}) {
  const reduced = useReducedMotion()
  return (
    <button
      type="button"
      disabled={disabled}
      aria-busy={busy || undefined}
      onClick={onClick}
      className={cn(BUTTON_PRIMARY, "disabled:opacity-35", hue && "hover:brightness-[1.06] focus-visible:brightness-[1.06]", className)}
      style={hue ? { background: hue, color: onHue, transition: "filter 150ms, scale 150ms, opacity 150ms" } : undefined}
    >
      <AnimatePresence mode="wait" initial={false}>
        <motion.span
          key={state}
          className="inline-flex items-center gap-2"
          initial={reduced ? { opacity: 0 } : { opacity: 0, y: 4, filter: "blur(2px)" }}
          animate={{ opacity: 1, y: 0, filter: "blur(0px)" }}
          exit={reduced ? { opacity: 0 } : { opacity: 0, y: -4, filter: "blur(2px)" }}
          transition={{ duration: 0.15, ease: EASE }}
        >
          {label}
        </motion.span>
      </AnimatePresence>
    </button>
  )
}

"use client"

import { useEffect, useId, useRef, useState, type ReactNode } from "react"

import { cn } from "@/lib/utils"

/* Amount Tip: the formula behind a figure, shown when the figure is pointed at, focused or
   tapped (2026-10-02 audit: every number stays derivable, and a line that is not read first
   keeps its formula here instead of printing it). The card is the library popover of spec
   14.6: radius 12, an 8% hairline, the ground 6% foreground over the background and the
   popover shadow; the text 11px at /90. It opens after 320ms so a pass across a row does
   not flash it, closes on leave, blur and Escape, and a tap toggles it on touch.
   Shipped beside the components that import it (the tickets, the swaps, Crypto Fiat).
   2026-10-02 round 2: the card comes in instead of appearing: 150ms, opacity and a 3px rise
   toward its figure (opacity alone with reduced motion), through the Web Animations API so the
   file still ships with no motion dependency. Amount now uses it for its hover card. */

/** the card's entrance, run once when it mounts; on transform, so a centred card's own
 *  translate (Tailwind's -translate-x-1/2) is left alone */
const enter = (side: "top" | "bottom") => (el: HTMLSpanElement | null) => {
  if (!el || el.dataset.in || typeof el.animate !== "function") return
  el.dataset.in = "1"
  const still = el.ownerDocument.defaultView?.matchMedia?.("(prefers-reduced-motion: reduce)").matches
  const from = side === "top" ? "3px" : "-3px"
  el.animate(still ? [{ opacity: 0 }, { opacity: 1 }] : [{ opacity: 0, transform: `translateY(${from})` }, { opacity: 1, transform: "none" }], {
    duration: 150,
    easing: "cubic-bezier(0.16, 1, 0.3, 1)",
  })
}

export function Tip({
  tip,
  children,
  className,
  side = "top",
  align = "end",
}: {
  tip: ReactNode
  children: ReactNode
  className?: string
  side?: "top" | "bottom"
  /** which edge of the figure the card lines up with */
  align?: "start" | "center" | "end"
}) {
  const [open, setOpen] = useState(false)
  const timer = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  const id = useId()
  useEffect(() => () => clearTimeout(timer.current), [])
  const show = () => {
    clearTimeout(timer.current)
    timer.current = setTimeout(() => setOpen(true), 320)
  }
  const hide = () => {
    clearTimeout(timer.current)
    setOpen(false)
  }
  return (
    <span
      aria-describedby={open ? id : undefined}
      className={cn("relative", className)}
      onMouseEnter={show}
      onMouseLeave={hide}
      onFocus={show}
      onBlur={hide}
      onKeyDown={(e) => {
        if (e.key === "Escape") hide()
      }}
      onPointerUp={(e) => {
        if (e.pointerType === "touch") setOpen((o) => !o)
      }}
    >
      {children}
      {open && (
        <span
          id={id}
          role="status"
          ref={enter(side)}
          className={cn(
            "pointer-events-none absolute z-50 w-max max-w-[260px] rounded-[12px] border border-foreground/[0.08] px-2.5 py-1.5 text-left text-[11px] font-normal leading-[1.45] text-foreground/90",
            side === "top" ? "bottom-full mb-1.5" : "top-full mt-1.5",
            align === "end" ? "right-0" : align === "start" ? "left-0" : "left-1/2 -translate-x-1/2",
          )}
          style={{
            background: "var(--tip-fill, color-mix(in srgb, var(--foreground) 6%, var(--background)))",
            boxShadow: "0 8px 24px var(--card-shadow, rgba(0,0,0,0.35))",
          }}
        >
          {tip}
        </span>
      )}
    </span>
  )
}
